def metric(data: pd.DataFrame) -> float:
    import numpy as np

    validities = np.array([0.95, 0.85, 0.75, 0.65, 0.55])

    agree_matches = 0
    agree_total = 0
    conflict_matches = 0
    conflict_total = 0

    for _, row in data.iterrows():
        a = np.array(row['option_a_ratings'])
        b = np.array(row['option_b_ratings'])
        resp = int(row['response'])

        # Find TTB winner
        ttb_winner = -1
        for i in range(5):
            if a[i] > b[i]:
                ttb_winner = 0
                break
            elif b[i] > a[i]:
                ttb_winner = 1
                break

        if ttb_winner == -1:
            continue

        # Find WADD winner
        wadd_a = np.sum(a * validities)
        wadd_b = np.sum(b * validities)
        if wadd_a > wadd_b:
            wadd_winner = 0
        elif wadd_b > wadd_a:
            wadd_winner = 1
        else:
            continue

        # Check if TTB and WADD agree or conflict
        if ttb_winner == wadd_winner:
            agree_total += 1
            if resp == ttb_winner:
                agree_matches += 1
        else:
            conflict_total += 1
            if resp == ttb_winner:
                conflict_matches += 1

    p_agree = agree_matches / agree_total if agree_total > 0 else 0.5
    p_conflict = conflict_matches / conflict_total if conflict_total > 0 else 0.5

    return float(p_agree - p_conflict)

